/* V20 拉克丝技能特效重做（原创绘制）：
 * Q 光之束缚：白金光球+棱彩光环+光尾；命中禁锢时目标脚下两道光环+光柱。
 * W 曲光屏障：旋转的棱镜法杖+彩虹光尾；被护盾的单位身上一圈流动的彩虹光晕。
 * E 透光奇点：飞行中脉动光球；落地后形成金色光域（旋转星芒、脉动外环、符文内环）；引爆时白光闪爆+放射光束+多重冲击环。
 * R 终极闪光：前摇时沿路径闪烁的细光线与向法杖汇聚的光点；释放时巨型光束（白色核心+金色/彩虹外缘），逐渐收窄淡出。 */
(()=>{'use strict';
const GOLD='255,226,122',WHITE='255,252,232',RAIN=['255,120,140','255,190,90','255,240,120','140,255,170','120,200,255','190,140,255'];
const hash=n=>{let x=Math.sin(n*12.9898)*43758.5453;return x-Math.floor(x)};
function star(ctx,x,y,r,a){ctx.beginPath();for(let i=0;i<8;i++){let rr=i%2?r*.35:r,an=a+i*Math.PI/4;ctx.lineTo(x+Math.cos(an)*rr,y+Math.sin(an)*rr)}ctx.closePath();ctx.fill()}
function zone(ctx,z,T){let k=Math.min(1,(T-z.start)/.2),life=z.until?Math.max(0,(z.until-T)/Math.max(.1,z.until-z.start)):1;ctx.save();ctx.translate(z.x,z.y);ctx.globalAlpha=k;
 let g=ctx.createRadialGradient?ctx.createRadialGradient(0,0,z.r*.1,0,0,z.r):null;if(g){g.addColorStop(0,'rgba('+WHITE+',.35)');g.addColorStop(.6,'rgba('+GOLD+',.16)');g.addColorStop(1,'rgba('+GOLD+',.32)');ctx.fillStyle=g}else ctx.fillStyle='rgba('+GOLD+',.2)';ctx.beginPath();ctx.arc(0,0,z.r,0,Math.PI*2);ctx.fill();
 ctx.beginPath();ctx.arc(0,0,z.r*(.97+.03*Math.sin(T*8)),0,Math.PI*2);ctx.strokeStyle='rgba('+GOLD+',.9)';ctx.lineWidth=4;ctx.stroke();
 ctx.setLineDash?.([6,10]);ctx.lineDashOffset=T*30;ctx.beginPath();ctx.arc(0,0,z.r*.62,0,Math.PI*2);ctx.strokeStyle='rgba('+WHITE+',.7)';ctx.lineWidth=2;ctx.stroke();ctx.setLineDash?.([]);
 for(let i=0;i<10;i++){let a=hash(i)*Math.PI*2+T*(.6+hash(i+3)),r=z.r*(.2+.7*hash(i+9)),tw=.5+.5*Math.sin(T*6+i*2);ctx.fillStyle='rgba('+WHITE+','+(.4+.5*tw)+')';star(ctx,Math.cos(a)*r,Math.sin(a)*r,4+5*tw,T+i)}
 ctx.fillStyle='rgba('+WHITE+',.9)';star(ctx,0,0,14+4*Math.sin(T*5),T*1.5);ctx.restore()}
function boom(ctx,b,T){let k=(T-b.start)/.5;if(k>=1)return;let e=1-Math.pow(1-k,3);ctx.save();ctx.translate(b.x,b.y);ctx.globalAlpha=1-k;
 if(k<.3){ctx.beginPath();ctx.arc(0,0,b.r*(.5+.5*k/.3),0,Math.PI*2);ctx.fillStyle='rgba('+WHITE+','+(.8*(1-k/.3))+')';ctx.fill()}
 for(let j=0;j<3;j++){let rr=b.r*(.4+.75*e)-j*16;if(rr<=0)continue;ctx.beginPath();ctx.arc(0,0,rr,0,Math.PI*2);ctx.strokeStyle='rgba('+(j?GOLD:WHITE)+','+(.9-j*.25)+')';ctx.lineWidth=6-j*2;ctx.stroke()}
 for(let i=0;i<16;i++){let a=i*Math.PI/8+b.start;ctx.beginPath();ctx.moveTo(Math.cos(a)*b.r*.25*e,Math.sin(a)*b.r*.25*e);ctx.lineTo(Math.cos(a)*b.r*(.6+.6*e),Math.sin(a)*b.r*(.6+.6*e));ctx.strokeStyle='rgba('+RAIN[i%6]+',.8)';ctx.lineWidth=3;ctx.stroke()}ctx.restore()}
function bind(ctx,t,T){let B=t.luxBind;if(!B||T>B.until||!(t.hp>0))return;let r=(t.radius||22)+14;ctx.save();ctx.translate(t.x,t.y);for(let j=0;j<2;j++){ctx.beginPath();ctx.ellipse(0,-6-j*22,r*(1-j*.15),r*.38*(1-j*.15),0,0,Math.PI*2);ctx.strokeStyle='rgba('+GOLD+','+(.85+.15*Math.sin(T*12+j))+')';ctx.lineWidth=4;ctx.stroke()}ctx.globalAlpha=.55;for(let i=0;i<4;i++){let a=i*Math.PI/2+T*2;ctx.fillStyle='rgba('+WHITE+',.6)';ctx.fillRect(Math.cos(a)*r*.8-2,-60,4,54)}ctx.restore()}
function halo(ctx,u,T){if(!(u.shields||[]).some(s=>s.source?.hero==='lux'&&(s.amount||0)>0&&s.until>T))return;let r=(u.radius||22)+20;ctx.save();ctx.translate(u.x,u.y-14);ctx.lineWidth=3;for(let i=0;i<6;i++){let a=T*2.2+i*Math.PI/3;ctx.beginPath();ctx.arc(0,0,r,a,a+Math.PI/3*.85);ctx.strokeStyle='rgba('+RAIN[i]+',.75)';ctx.stroke()}ctx.beginPath();ctx.arc(0,0,r+5,0,Math.PI*2);ctx.strokeStyle='rgba('+WHITE+',.35)';ctx.lineWidth=1.5;ctx.stroke();ctx.restore()}
function beam(ctx,u,T){let pc=u.pendingCast;if(pc?.i===3&&pc.end){let w=u.skills?.[3]?.windup||1,k=Math.max(0,Math.min(1,1-(u.castWindup||0)/w));ctx.save();ctx.globalAlpha=.4+.5*k;ctx.beginPath();ctx.moveTo(u.x,u.y);ctx.lineTo(pc.end.x,pc.end.y);ctx.strokeStyle='rgba('+WHITE+','+(.5+.5*Math.abs(Math.sin(T*30)))+')';ctx.lineWidth=2+4*k;ctx.stroke();for(let i=0;i<14;i++){let ph=(T*1.6+hash(i))%1,a=hash(i+5)*Math.PI*2,r=90*(1-ph);ctx.fillStyle='rgba('+GOLD+','+(.3+.7*ph)+')';ctx.beginPath();ctx.arc(u.x+Math.cos(a)*r,u.y+Math.sin(a)*r-20,2+3*ph,0,Math.PI*2);ctx.fill()}ctx.beginPath();ctx.arc(u.x,u.y-20,8+14*k,0,Math.PI*2);ctx.fillStyle='rgba('+WHITE+','+(.4+.5*k)+')';ctx.fill();ctx.restore()}
 let f=u.luxRFx;if(!f)return;let k=(T-f.start)/.6;if(k>=1){u.luxRFx=null;return}let ang=Math.atan2(f.y1-f.y0,f.x1-f.x0),L=Math.hypot(f.x1-f.x0,f.y1-f.y0),W=f.width*(1-.6*k);ctx.save();ctx.translate(f.x0,f.y0);ctx.rotate(ang);ctx.globalAlpha=1-k*k;
 for(let i=0;i<6;i++){ctx.fillStyle='rgba('+RAIN[i]+',.22)';ctx.fillRect(0,-W/2*(1-i*.08)+i*.5,L,W*(1-i*.08)/6+2)}
 let g=ctx.createLinearGradient?ctx.createLinearGradient(0,-W/2,0,W/2):null;if(g){g.addColorStop(0,'rgba('+GOLD+',0)');g.addColorStop(.3,'rgba('+GOLD+',.75)');g.addColorStop(.5,'rgba('+WHITE+',1)');g.addColorStop(.7,'rgba('+GOLD+',.75)');g.addColorStop(1,'rgba('+GOLD+',0)');ctx.fillStyle=g}else ctx.fillStyle='rgba('+WHITE+',.8)';ctx.fillRect(0,-W/2,L,W);
 for(let i=0;i<20;i++){let x=hash(i+f.start)*L,y=(hash(i*3+f.start)-.5)*W;ctx.fillStyle='rgba('+WHITE+',.9)';star(ctx,x,y,4+6*hash(i),T*3+i)}
 ctx.beginPath();ctx.arc(0,0,W*.6,0,Math.PI*2);ctx.fillStyle='rgba('+WHITE+',.8)';ctx.fill();ctx.restore()}
function draw(ctx,player,units,T,seen){for(let u of units){if(!(u.hp>0)||u.death>0)continue;let vis=!seen||seen(u);if(vis){bind(ctx,u,T);halo(ctx,u,T)}if(u.hero!=='lux')continue;if(u.luxEZone&&T<u.luxEZone.until)zone(ctx,u.luxEZone,T);if(u.luxEBoom)boom(ctx,u.luxEBoom,T);if(vis||u.team===player?.team)beam(ctx,u,T)}}
function projectile(ctx,p,spin){if(p.luxOrb){ctx.shadowColor='rgba('+GOLD+',1)';ctx.shadowBlur=22;let r=13+2*Math.sin(spin*3);for(let i=1;i<=4;i++){ctx.fillStyle='rgba('+GOLD+','+(.4-.08*i)+')';ctx.beginPath();ctx.arc(-i*11,0,r-i*2,0,Math.PI*2);ctx.fill()}ctx.fillStyle='rgba('+WHITE+',1)';ctx.beginPath();ctx.arc(0,0,r,0,Math.PI*2);ctx.fill();ctx.strokeStyle='rgba('+GOLD+',1)';ctx.lineWidth=3;ctx.stroke();return true}
 if(p.boomerang){ctx.shadowColor='rgba('+WHITE+',1)';ctx.shadowBlur=14;for(let i=0;i<6;i++){ctx.strokeStyle='rgba('+RAIN[i]+',.55)';ctx.lineWidth=4;ctx.beginPath();ctx.moveTo(-14-i*7,(i-2.5)*2);ctx.lineTo(-40-i*7,(i-2.5)*2);ctx.stroke()}ctx.rotate(spin*1.5);ctx.fillStyle='rgba('+WHITE+',1)';ctx.beginPath();ctx.moveTo(0,-15);ctx.lineTo(9,0);ctx.lineTo(0,15);ctx.lineTo(-9,0);ctx.closePath();ctx.fill();ctx.strokeStyle='rgba('+GOLD+',1)';ctx.lineWidth=2.5;ctx.stroke();return true}
 if(p.index===0){ctx.shadowColor='rgba('+GOLD+',1)';ctx.shadowBlur=18;let tg=ctx.createLinearGradient?.(-60,0,0,0);if(tg){tg.addColorStop(0,'rgba('+GOLD+',0)');tg.addColorStop(1,'rgba('+WHITE+',.85)')}ctx.strokeStyle=tg||'rgba('+WHITE+',.6)';ctx.lineWidth=10;ctx.lineCap='round';ctx.beginPath();ctx.moveTo(-60,0);ctx.lineTo(-6,0);ctx.stroke();ctx.fillStyle='rgba('+WHITE+',1)';ctx.beginPath();ctx.arc(0,0,11,0,Math.PI*2);ctx.fill();ctx.rotate(spin*.8);for(let i=0;i<6;i++){ctx.rotate(Math.PI/3);ctx.strokeStyle='rgba('+RAIN[i]+',.85)';ctx.lineWidth=2.5;ctx.beginPath();ctx.arc(0,0,17,0,Math.PI/4);ctx.stroke()}return true}return false}
window.LuxFxV20={draw,projectile};
})();
